import random


class ApiError(Exception):
    def __init__(self, status):
        super().__init__(status)
        self.status = status


def retry(call, attempts=5, base=0.5, cap=8, jitter=False, sleep=lambda s: None):
    return call()


results = iter([ApiError(503), ApiError(503), {"ok": True}])


def flaky():
    r = next(results)
    if isinstance(r, Exception):
        raise r
    return r
